<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Expiring Employee Documents</title><link rel="stylesheet" href="../public/css/style.css"><link rel="stylesheet" href="../public/css/dashboard.css?v=20260909-2"><link rel="stylesheet" href="../public/css/employee-documents-fixes.css?v=20260921-1"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><style>
*{box-sizing:border-box}body{margin:0;background:#f4f7fa;color:#19384d}.tc-sidebar{position:fixed;inset:0 auto 0 0;width:272px;height:100vh;z-index:1000;display:flex;flex-direction:column;overflow:hidden;background:#0f2238;color:#dcebfa;padding:14px 12px;box-shadow:8px 0 32px rgba(15,23,42,.14)}.tc-brand{display:flex;gap:10px;align-items:center;padding:4px 6px 14px}.tc-brand img{width:42px;height:42px;object-fit:contain}.tc-brand strong,.tc-brand small,.tc-status strong,.tc-status small{display:block}.tc-brand small,.tc-status small{color:#9fb7d1;font-size:10px}.tc-sidebar-close{display:none}.tc-status{display:flex;gap:10px;align-items:center;margin:0 3px 14px;padding:10px;border-radius:12px;background:rgba(30,136,229,.12);border:1px solid rgba(125,184,237,.18)}.tc-status>span{width:9px;height:9px;border-radius:50%;background:#43a047}.tc-sidebar nav{display:flex;flex:1;min-height:0;flex-direction:column;gap:2px;overflow-y:auto}.tc-nav-section{padding:12px 10px 5px;color:#7897b5;font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.11em}.tc-sidebar nav a{display:flex;align-items:center;gap:10px;min-height:38px;padding:9px 10px;border-radius:10px;color:#dcebfa;text-decoration:none;font-size:13px;font-weight:800}.tc-sidebar nav a span{width:26px;height:26px;display:grid;place-items:center;border-radius:8px;background:rgba(255,255,255,.08);color:#bfd8f2}.tc-sidebar nav a em{font-style:normal}.tc-sidebar nav a:hover,.tc-sidebar nav a.active{background:#163c61;color:#fff;border-left:3px solid #16a085}.tc-menu-link{margin-top:auto!important;border-top:1px solid #294158}.tc-logout-link{color:#ffcaca!important}.tc-sidebar-scrim{display:none}.ed-expiring-main{margin-left:272px;min-height:100vh;padding:24px}.page-head,.panel{background:#fff;border:1px solid #dce8ef;border-radius:14px;padding:18px;box-shadow:0 7px 18px rgba(18,52,77,.05)}.page-head{display:flex;align-items:center;justify-content:space-between}.page-head h1{margin:0;color:#083b5c;font-size:21px}.page-head p{margin:5px 0 0;color:#64798a}.panel{margin-top:16px}.table-wrap{overflow:auto}.table{width:100%;min-width:920px;border-collapse:collapse}.table th,.table td{padding:12px;border-bottom:1px solid #e4edf2;text-align:left;vertical-align:middle}.table th{background:#f4f8fa;color:#516a7e;font-size:12px}.table td{font-size:13px}.table small{color:#64798a}.badge{display:inline-block;padding:5px 9px;border-radius:999px;background:#fff0cc;color:#946000;font-size:10px;font-weight:900}.actions{display:flex;gap:7px}.btn{display:inline-flex;align-items:center;gap:6px;border-radius:8px;padding:9px 11px;background:#083b5c;color:#fff;text-decoration:none;font-weight:800}.btn.light{background:#edf4f7;color:#214b64}.empty{text-align:center!important;padding:30px!important;color:#64798a}@media(max-width:900px){.ed-expiring-main{margin-left:0;padding:14px}.tc-sidebar{display:none}.page-head{align-items:flex-start;gap:12px}.page-head h1{font-size:17px}}
</style><link rel="stylesheet" href="../public/css/module-theme.css?v=18">
<script defer src="../public/js/nursync-ui.js?v=4"></script></head><body class="module-ui"><?php include '../includes/employee_documents_sidebar.php';?><main class="ed-expiring-main"><header class="page-head"><div><h1><i class="fa-solid fa-hourglass-half"></i> Expiring Soon</h1><p>Only verified files expiring within the next 60 days are shown.</p></div><span class="badge"><?=count($docs)?> FILE<?=count($docs)===1?'':'S'?></span></header><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Employee</th><th>Department</th><th>Expiring File</th><th>Category</th><th>Expiration Date</th><th>Days Remaining</th><th>Actions</th></tr></thead><tbody><?php foreach($docs as$d):$days=max(0,(int)floor((strtotime($d['expiry_date'])-strtotime(date('Y-m-d')))/86400));?><tr><td><strong><?=h($d['employee_name'])?></strong></td><td><?=h(str_replace('_',' ',$d['department']??''))?></td><td><strong><?=h($d['document_type'])?></strong></td><td><?=h($d['category'])?></td><td><?=edDate($d['expiry_date'])?></td><td><span class="badge"><?=$days?> day<?=$days===1?'':'s'?></span></td><td><div class="actions"><a class="btn light" target="_blank" rel="noopener" href="employee_documents.php?download=<?=$d['id']?>"><i class="fa-solid fa-eye"></i> View</a><a class="btn" href="employee_documents.php?view=renew&amp;document_id=<?=$d['id']?>"><i class="fa-solid fa-rotate"></i> Renew</a></div></td></tr><?php endforeach;?><?php if(!$docs):?><tr><td colspan="7" class="empty">No files are expiring within the next 60 days.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
